def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 seen=set(); blocks=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=1 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c))
   for y,x in q:
    for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=a<h and 0<=b<w and grid[a][b]==1 and (a,b) not in seen:
      seen.add((a,b)); q.append((a,b))
   blocks.append((min(y for y,x in q),min(x for y,x in q),max(y for y,x in q),max(x for y,x in q)))
 edges=[]
 for i,(a,b,c,d) in enumerate(blocks):
  for j in range(i+1,len(blocks)):
   e,f,g,k=blocks[j]
   if a==e and c==g: edges.append((max(f-d-1,b-k-1),i,j,'h'))
   elif b==f and d==k: edges.append((max(e-c-1,a-g-1),i,j,'v'))
 p=list(range(len(blocks)))
 def root(i):
  while p[i]!=i:
   p[i]=p[p[i]]; i=p[i]
  return i
 for dist,i,j,axis in sorted(edges):
  u,v=root(i),root(j)
  if u==v: continue
  p[u]=v
  a,b,c,d=blocks[i]; e,f,g,k=blocks[j]
  if axis=='h':
   for y in range(a,c+1):
    for x in range(min(b,f),max(d,k)+1):
     if out[y][x]==0: out[y][x]=5
  else:
   for y in range(min(a,e),max(c,g)+1):
    for x in range(b,d+1):
     if out[y][x]==0: out[y][x]=5
 return out

